<?php
namespace App\Services\HR;
use App\Models\AttendanceDevice;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class AttendanceDeviceService { public function create(array $data,int $actorId): AttendanceDevice{return DB::transaction(fn()=>AttendanceDevice::create($data+['created_by'=>$actorId,'updated_by'=>$actorId]));} public function update(AttendanceDevice $device,array $data,int $actorId): AttendanceDevice{return DB::transaction(function()use($device,$data,$actorId){if(isset($data['device_code'])&&$data['device_code']!==$device->device_code&&$this->hasHistory($device))throw ValidationException::withMessages(['device_code'=>'Device Code cannot be changed because this device has historical attendance data.']);$device->update($data+['updated_by'=>$actorId]);return $device->fresh();});} public function activate(AttendanceDevice $device,int $actorId): AttendanceDevice{$device->update(['status'=>'active','updated_by'=>$actorId]);return $device->fresh();} public function deactivate(AttendanceDevice $device,int $actorId): AttendanceDevice{$device->update(['status'=>'inactive','updated_by'=>$actorId]);return $device->fresh();} public function delete(AttendanceDevice $device): void{if($this->hasHistory($device))throw ValidationException::withMessages(['device'=>'This device has historical logs, mappings, or sync history and can only be deactivated.']);$device->delete();} public function hasHistory(AttendanceDevice $device): bool{return $device->logs()->exists()||$device->mappings()->exists()||$device->syncLogs()->exists();} }
